44	/// Per-field cap on the overwritten content copied into an audit entry — applied to the source
45	/// AND the description. The value is attacker-influenced text landing in an append-only table,
46	/// so it is bounded rather than trusted.
47	pub const MAX_AUDITED_SOURCE_BYTES: usize = 8 * 1024;
48	
49	/// Boot-time reconciliation dependencies. A named-field `*Deps` struct with generic
50	/// `IdGenerator`/`Clock`, mirroring `BootstrapAdminSeederDeps` and `RoleServiceDeps`.
51	pub struct ReconcileStarterDeps<I: IdGenerator, C: Clock> {
52	    pub policies: Arc<dyn SystemPolicyReconciler>,
53	    pub roles: Arc<dyn SystemRoleReconciler>,
54	    pub audit: Arc<dyn AuditLog>,
55	    pub ids: I,
56	    pub clock: C,
57	}
58	
59	fn count(outcome_label: &'static str) {
60	    counter!(names::IAM_STARTER_POLICY_RECONCILES_TOTAL, "outcome" => outcome_label).increment(1);
61	}
62	
63	/// Caps one copied text field at [`MAX_AUDITED_SOURCE_BYTES`], walking BACK to the nearest char
64	/// boundary so `text[..end]` can never split a multi-byte character — slicing mid-character
65	/// panics, and this runs inside `AppState::new`, so the panic would kill the replica before it
66	/// served a request. The overwritten text is attacker-influenced, so it may well be the operator
67	/// who chose where byte 8192 lands. A walked-back result is SHORTER than the cap.
68	fn truncate_audited_text(text: &str) -> (String, bool) {
69	    if text.len() <= MAX_AUDITED_SOURCE_BYTES {
70	        return (text.to_string(), false);
71	    }
72	    let mut end = MAX_AUDITED_SOURCE_BYTES;
73	    while !text.is_char_boundary(end) {
74	        end -= 1;
75	    }
76	    (text[..end].to_string(), true)
77	}
