79	/// Why a `reconcile_system` failure is (or is not) fatal, decided against the pre-loop snapshot
80	/// of persisted ids. Split out as a pure function so each branch — and, critically, the message
81	/// each one selects — is unit-testable: the three cases are genuinely different operational
82	/// stories, and reporting one as another sends on-call the wrong way.
83	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
84	enum FailureKind {
85	    /// The row is persisted: it governed decisions perfectly well before this change.
86	    Survivable,
87	    /// The snapshot was readable and this id was NOT in it — the row really is missing.
88	    FatalMissingRow,
89	    /// The snapshot could not be read at all, so this row's existence is UNKNOWN. Fail closed,
90	    /// but never claim the row is missing: it usually is not.
91	    FatalUnknownSnapshot,
92	}
93	
94	/// `snapshot == None` means the pre-loop read itself failed (see [`reconcile_policies`]). Shared
95	/// by both halves — `key` is a `policy_id` for the policy loop and a `role.key` for the role one.
96	fn classify_failure(snapshot: Option<&[String]>, key: &str) -> FailureKind {
97	    match snapshot {
98	        Some(ids) if ids.iter().any(|id| id == key) => FailureKind::Survivable,
99	        Some(_) => FailureKind::FatalMissingRow,
100	        None => FailureKind::FatalUnknownSnapshot,
101	    }
102	}
