104	/// Reconciles every `authz::roles::starter_policies()` document. Only a failure to SEED an
105	/// absent policy propagates (see the module docs).
106	pub async fn reconcile_policies<I: IdGenerator, C: Clock>(deps: &ReconcileStarterDeps<I, C>) -> Result<(), AuthzError> {
107	    // Captured once, BEFORE any convergence, so every policy is judged against ONE consistent
108	    // basis and the whole loop costs one full-table read rather than nine.
109	    //
110	    // A FAILED read degrades to `None`, which [`classify_failure`] treats as fatal — the
111	    // conservative direction, since the alternative is booting a replica with an incomplete
112	    // policy set that denies everything. It is warned about rather than swallowed: a blip here
113	    // against an intact database turns every later failure fatal, and an operator reading only
114	    // the fatal line would otherwise be told the policy set is incomplete when it is not.
115	    let existing_ids: Option<Vec<String>> = match deps.policies.existing_policy_ids().await {
116	        Ok(ids) => Some(ids),
117	        Err(err) => {
118	            tracing::warn!(
119	                error = %err,
120	                "could not read the persisted policy-id snapshot; every starter policy reconciliation failure this boot will be treated as fatal because no row can be proven to already exist"
121	            );
122	            None
123	        }
124	    };
125	
126	    for doc in authz_roles::starter_policies() {
127	        let outcome = match deps.policies.reconcile_system(&doc, STARTER_POLICY_REVISION).await {
128	            Ok(outcome) => outcome,
129	            Err(err) => {
130	                count("failed");
131	                match classify_failure(existing_ids.as_deref(), &doc.policy_id) {
132	                    // The row exists: it governed decisions perfectly well before this change,
133	                    // so keeping it for one more boot beats refusing to start (SMA-477 D12).
134	                    FailureKind::Survivable => {
135	                        tracing::error!(policy_id = %doc.policy_id, error = %err, "starter policy reconciliation failed; keeping the stored row for this boot");
136	                        continue;
137	                    }
138	                    // The row is MISSING and could not be written. `AppState::new` guarantees
139	                    // the initial snapshot compiles at least the starter set; booting past this
140	                    // would compile a partial one, which denies everything.
141	                    FailureKind::FatalMissingRow => {
142	                        tracing::error!(policy_id = %doc.policy_id, error = %err, "failed to seed a missing starter policy; refusing to boot with an incomplete policy set");
143	                        return Err(err);
144	                    }
145	                    // Deliberately NOT the message above: the row is probably fine, we simply
146	                    // could not prove it. Says so, and points at the warning that explains why.
147	                    FailureKind::FatalUnknownSnapshot => {
148	                        tracing::error!(
149	                            policy_id = %doc.policy_id,
150	                            error = %err,
151	                            "starter policy reconciliation failed and the policy-id snapshot was unreadable (see the earlier warning), so this row cannot be proven to exist; refusing to boot rather than risk an incomplete policy set"
152	                        );
153	                        return Err(err);
154	                    }
155	                }
156	            }
157	        };
158	        count(outcome.metric_label());
159	
160	        match &outcome {
161	            StarterPolicyOutcome::Unchanged => {}
162	            StarterPolicyOutcome::Absent => tracing::info!(policy_id = %doc.policy_id, "seeded starter policy"),
163	            StarterPolicyOutcome::Reconciled => {
164	                tracing::info!(policy_id = %doc.policy_id, "converged starter policy to the code-defined content")
165	            }
166	            StarterPolicyOutcome::StaleBinary { provenance_ok: true } => tracing::info!(
167	                policy_id = %doc.policy_id,
168	                revision = STARTER_POLICY_REVISION,
169	                "starter policy was written by a newer release; leaving it in place"
170	            ),
171	            // A revision this binary cannot beat, over a row that does NOT look like a newer
172	            // release wrote it — a forged `starter_revision` is one `UPDATE`, and because the
173	            // revision check runs first and writes nothing, it would otherwise exempt the row
174	            // from convergence permanently and at INFO. Deferring is still the only safe action
175	            // (D11: an older binary rewriting a newer release's row is what monotonicity forbids),
176	            // so this WARNs about a divergence it explicitly will NOT repair.
177	            //
178	            // NO audit row, deliberately. Unlike a converged `ExternallyModified` — a one-off,
179	            // because the next boot finds the row repaired — this recurs on EVERY boot of EVERY
180	            // replica until a human acts, and `audit_log` is append-only. That is exactly the
181	            // reasoning D13 applies to orphans; the WARN and the `externally_modified` metric
182	            // carry the signal instead.
183	            StarterPolicyOutcome::StaleBinary { provenance_ok: false } => tracing::warn!(
184	                policy_id = %doc.policy_id,
185	                revision = STARTER_POLICY_REVISION,
186	                "a starter policy row claims a revision newer than this binary's but its provenance does not check out: the row was written outside this service and is DIVERGED from the code-defined content. This binary will NOT repair it — rewriting a row a newer release may have written is what the revision guard exists to prevent. Deploy a build whose STARTER_POLICY_REVISION exceeds the stored starter_revision, or repair the row directly"
187	            ),
188	            StarterPolicyOutcome::Adopted { content_changed, previous_content } => {
189	                if *content_changed {
190	                    tracing::info!(policy_id = %doc.policy_id, "adopted a starter policy with no recorded provenance and converged its content");
191	                    if let Some(previous) = previous_content {
192	                        record_reconcile_audit(deps, &doc, "adopted_unfingerprinted", true, previous).await;
193	                    }
194	                } else {
195	                    tracing::debug!(policy_id = %doc.policy_id, "stamped provenance on an already-matching starter policy");
196	                }
197	            }
198	            StarterPolicyOutcome::ExternallyModified { content_changed, previous_content } => {
199	                tracing::warn!(
200	                    policy_id = %doc.policy_id,
201	                    content_changed = *content_changed,
202	                    "a system-owned starter policy was modified outside this service; converging it back to the code-defined content"
203	                );
204	                record_reconcile_audit(deps, &doc, "external_modification", *content_changed, previous_content).await;
205	            }
206	        }
207	    }
208	
209	    // A failed scan degrades to "no orphans", which is indistinguishable from a healthy database
210	    // in the logs — so it is warned about rather than swallowed, exactly as the `existing_ids`
211	    // read above is. Never fatal: this is a reporting scan, and every row it would have named is
212	    // still compiling and still governing.
213	    let orphans = match deps.policies.orphaned_system_policy_ids(STARTER_POLICY_IDS).await {
214	        Ok(ids) => ids,
215	        Err(err) => {
216	            tracing::warn!(error = %err, "could not scan for orphaned system policy rows; retired starter policies go unreported this boot");
217	            Vec::new()
218	        }
219	    };
220	    for orphan in orphans {
221	        count("orphaned");
222	        tracing::warn!(
223	            policy_id = %orphan,
224	            "a system-owned policy row is no longer code-defined; it still compiles and still links grants, and DeletePolicy refuses to remove it"
225	        );
226	    }
227	    Ok(())
228	}
