230	/// One audit entry recording content this boot is about to destroy. Best-effort by design
231	/// (SMA-477 D9): the convergence already committed, so a failed audit write is logged, never
232	/// propagated — refusing to start over a bookkeeping failure would be a self-inflicted outage.
233	async fn record_reconcile_audit<I: IdGenerator, C: Clock>(
234	    deps: &ReconcileStarterDeps<I, C>,
235	    doc: &PolicyDocument,
236	    reason: &str,
237	    content_changed: bool,
238	    previous: &paigasus_iam_core::authz::reconcile::PolicyContent,
239	) {
240	    // BOTH copied fields are capped: they come from the same externally-modified row, so the
241	    // description is exactly as attacker-influenced as the source. Two flags rather than one —
242	    // `truncated` has always meant "the source was truncated" and stays that way.
243	    let (source, truncated) = truncate_audited_text(&previous.source);
244	    let (description, description_truncated) = truncate_audited_text(&previous.description);
245	    let entry = AuditEntry {
246	        id: deps.ids.new_audit_id(),
247	        occurred_at: deps.clock.now(),
248	        // No principal authorized this — a code deployment did (the SMA-468 posture).
249	        actor_prn: None,
250	        // The same action + Root resource every PutPolicy audit row uses, so these rows are
251	        // reachable by the standard `AuditFilter::resource_prn` query rather than a private one.
252	        action: "PutPolicy".to_string(),
253	        resource_prn: Some(root_prn().canonical()),
254	        outcome: AuditOutcome::Committed,
255	        determining_policies: vec![],
256	        detail: serde_json::json!({
257	            "policy_id": doc.policy_id,
258	            "source": "starter_policy_reconcile",
259	            "reason": reason,
260	            "content_changed": content_changed,
261	            "previous_content": {
262	                // The overwritten `kind`, as the wire string the column stores. Recorded rather
263	                // than dropped because a wrong `kind` is not cosmetic: a `template` persisted as
264	                // `static` makes `PolicyEngine::compile` parse template source as a static
265	                // policy, which fails `PolicySnapshot::new` and therefore boot — so it is
266	                // precisely the field an investigator needs to see was destroyed.
267	                "kind": policy_kind_str(previous.kind),
268	                "source": source,
269	                "description": description,
270	                "truncated": truncated,
271	                "description_truncated": description_truncated,
272	            },
273	        }),
274	        correlation_id: Some(deps.ids.new_correlation_id()),
275	    };
276	    if let Err(err) = deps.audit.record_out_of_band(&entry).await {
277	        tracing::error!(policy_id = %doc.policy_id, error = %err, "failed to record the starter-policy reconciliation audit entry");
278	    }
279	}
280	
281	/// Reconciles every `authz::roles::system_roles()` row. Drift in these columns is cosmetic (they
282	/// are introspectable-only), so a failure to CONVERGE is logged and skipped and nothing here is
283	/// ever audited — but a failure to SEED an absent row is fatal, exactly as on the policy half:
284	/// `role_grant.role_key` carries an FK to `role.key`, so booting past a missing `platform_admin`
285	/// row just moves the failure to the first bootstrap-admin grant, as a raw FK violation at
286	/// authentication time.
287	pub async fn reconcile_roles<I: IdGenerator, C: Clock>(deps: &ReconcileStarterDeps<I, C>) -> Result<(), AuthzError> {
288	    // One read before the loop, degrading to `None` on failure — the policy half's posture and
289	    // its reasoning verbatim (see [`reconcile_policies`]).
290	    let existing_keys: Option<Vec<String>> = match deps.roles.existing_role_keys().await {
291	        Ok(keys) => Some(keys),
292	        Err(err) => {
293	            tracing::warn!(
294	                error = %err,
295	                "could not read the persisted role-key snapshot; every system role reconciliation failure this boot will be treated as fatal because no row can be proven to already exist"
296	            );
297	            None
298	        }
299	    };
300	
301	    for role_def in authz_roles::system_roles() {
302	        match deps.roles.reconcile_role(&role_def).await {
303	            Ok(RoleOutcome::Inserted) => tracing::info!(role_key = %role_def.key, "seeded system role"),
304	            Ok(RoleOutcome::Updated) => tracing::info!(role_key = %role_def.key, "converged system role row to the code-defined catalog"),
305	            Ok(RoleOutcome::Unchanged) => {}
306	            Err(err) => {
307	                count("failed");
308	                match classify_failure(existing_keys.as_deref(), &role_def.key) {
309	                    // The row exists. Its columns are introspectable-only, so stale ones cost
310	                    // nothing for one boot — strictly better than refusing to start.
311	                    FailureKind::Survivable => {
312	                        tracing::error!(role_key = %role_def.key, error = %err, "system role reconciliation failed; keeping the stored row for this boot");
313	                    }
314	                    // The row is MISSING and could not be written. Every grant of this role
315	                    // takes an FK to it, so continuing defers the failure to the first
316	                    // authentication that needs it — a far more confusing outage than this one.
317	                    FailureKind::FatalMissingRow => {
318	                        tracing::error!(role_key = %role_def.key, error = %err, "failed to seed a missing system role; refusing to boot with an incomplete role catalog");
319	                        return Err(err);
320	                    }
321	                    // Deliberately NOT the message above: the row is probably fine, we simply
322	                    // could not prove it. Points at the warning that explains why.
323	                    FailureKind::FatalUnknownSnapshot => {
324	                        tracing::error!(
325	                            role_key = %role_def.key,
326	                            error = %err,
327	                            "system role reconciliation failed and the role-key snapshot was unreadable (see the earlier warning), so this row cannot be proven to exist; refusing to boot rather than risk an incomplete role catalog"
328	                        );
329	                        return Err(err);
330	                    }
331	                }
332	            }
333	        }
334	    }
335	
336	    let known: Vec<String> = authz_roles::system_roles().into_iter().map(|r| r.key).collect();
337	    let known_refs: Vec<&str> = known.iter().map(String::as_str).collect();
338	    // Warned about rather than swallowed, for the same reason the policy scan is: a failed scan
339	    // and a clean database are otherwise indistinguishable in the logs.
340	    let orphans = match deps.roles.orphaned_system_role_keys(&known_refs).await {
341	        Ok(keys) => keys,
342	        Err(err) => {
343	            tracing::warn!(error = %err, "could not scan for orphaned system role rows; retired roles go unreported this boot");
344	            Vec::new()
345	        }
346	    };
347	    for orphan in orphans {
348	        tracing::warn!(role_key = %orphan, "a system role row is no longer code-defined; existing grants of it still resolve");
349	    }
350	    Ok(())
351	}
352	
353	/// Policies first, then roles: every role template's `policy_id == Role::key ==
354	/// Role::template_id`, and `role.template_id` carries an FK to `policy.policy_id`
355	/// (`fk_role_template`), so the referenced policy row must exist before the role row can be
356	/// inserted.
357	pub async fn reconcile_starter<I: IdGenerator, C: Clock>(deps: &ReconcileStarterDeps<I, C>) -> Result<(), AuthzError> {
358	    reconcile_policies(deps).await?;
359	    reconcile_roles(deps).await
360	}
