386	    /// Returns a scripted outcome for every policy, recording what it was asked to reconcile.
387	    #[derive(Default)]
388	    struct ScriptedPolicies {
389	        outcome: Mutex<Option<StarterPolicyOutcome>>,
390	        fail: bool,
391	        seen: Mutex<Vec<String>>,
392	        orphans: Vec<String>,
393	        existing: Vec<String>,
394	        existing_calls: AtomicUsize,
395	        /// Simulates the pre-loop snapshot read itself failing, INDEPENDENTLY of `existing` —
396	        /// so a fixture can hold "every row is really there, but we could not read the list".
397	        existing_fails: bool,
398	        /// The `known` set the orphan scan was called with, captured so a test can prove the
399	        /// scan ran and was handed the code-defined ids.
400	        orphan_known: Mutex<Vec<String>>,
401	    }
402	
403	    impl ScriptedPolicies {
404	        fn with(outcome: StarterPolicyOutcome) -> Arc<Self> {
405	            Arc::new(ScriptedPolicies {
406	                outcome: Mutex::new(Some(outcome)),
407	                existing: all_starter_ids(),
408	                ..Default::default()
409	            })
410	        }
411	    }
412	
413	    #[async_trait::async_trait]
414	    impl SystemPolicyReconciler for ScriptedPolicies {
415	        async fn reconcile_system(&self, doc: &PolicyDocument, _revision: u32) -> Result<StarterPolicyOutcome, AuthzError> {
416	            self.seen.lock().unwrap().push(doc.policy_id.clone());
417	            if self.fail {
418	                return Err(backend_error("db down"));
419	            }
420	            Ok(self.outcome.lock().unwrap().clone().unwrap_or(StarterPolicyOutcome::Unchanged))
421	        }
422	        async fn orphaned_system_policy_ids(&self, known: &[&str]) -> Result<Vec<String>, AuthzError> {
423	            *self.orphan_known.lock().unwrap() = known.iter().map(|k| (*k).to_string()).collect();
424	            Ok(self.orphans.clone())
425	        }
426	        async fn existing_policy_ids(&self) -> Result<Vec<String>, AuthzError> {
427	            self.existing_calls.fetch_add(1, Ordering::SeqCst);
428	            if self.existing_fails {
429	                return Err(backend_error("snapshot read failed"));
430	            }
431	            Ok(self.existing.clone())
432	        }
433	    }
