464	    #[async_trait::async_trait]
465	    impl SystemRoleReconciler for ScriptedRoles {
466	        async fn reconcile_role(&self, role: &Role) -> Result<RoleOutcome, AuthzError> {
467	            self.seen.lock().unwrap().push(role.key.clone());
