3	//! Postgres-backed [`SystemRoleReconciler`] (SMA-477). Boot converges the `role` table to
4	//! `authz::roles::system_roles()`, where it previously only inserted missing rows — so a code
5	//! change to a role's description or scope kinds drifted forever, and silently.
6	//!
7	//! There is no `RoleRepository` port and this is not one: roles are code-defined, and this
8	//! table is only their persisted/introspectable form plus the `role_grant.role_key` FK target.
9	
10	use super::entities::role;
11	use crate::adapters::persistence::pg_policies::map_db_err;
12	use async_trait::async_trait;
13	use chrono::Utc;
14	use paigasus_iam_core::authz::reconcile::{RoleOutcome, StoredRoleRow, role_row_matches, scope_kinds_json};
15	use paigasus_iam_core::{AuthzError, Role, SystemRoleReconciler};
16	use sea_orm::{ActiveModelTrait, ColumnTrait, DatabaseConnection, EntityTrait, QueryFilter, QueryOrder, QuerySelect, Set, SqlErr};
17	
18	#[derive(Clone)]
19	pub struct PgSystemRoleReconciler {
20	    db: DatabaseConnection,
21	}
22	
23	impl PgSystemRoleReconciler {
24	    #[must_use]
25	    pub fn new(db: DatabaseConnection) -> Self {
26	        PgSystemRoleReconciler { db }
27	    }
28	}
