30	#[async_trait]
31	impl SystemRoleReconciler for PgSystemRoleReconciler {
32	    async fn reconcile_role(&self, role_def: &Role) -> Result<RoleOutcome, AuthzError> {
33	        let description = if role_def.description.is_empty() { None } else { Some(role_def.description.clone()) };
34	        let existing = role::Entity::find_by_id(role_def.key.clone()).one(&self.db).await.map_err(map_db_err)?;
35	
36	        let Some(existing) = existing else {
37	            let active = role::ActiveModel {
38	                key: Set(role_def.key.clone()),
39	                template_id: Set(role_def.template_id.clone()),
40	                scope_kinds: Set(scope_kinds_json(&role_def.scope_kinds)),
41	                description: Set(description),
42	                system: Set(role_def.system),
43	                created_at: Set(Utc::now()),
44	            };
45	            return match active.insert(&self.db).await {
46	                Ok(_) => Ok(RoleOutcome::Inserted),
47	                // A concurrent replica's boot won the race between our check and our insert.
48	                // The row exists either way, so this is an idempotent no-op, not an error.
49	                Err(e) if matches!(e.sql_err(), Some(SqlErr::UniqueConstraintViolation(_))) => Ok(RoleOutcome::Unchanged),
50	                Err(e) => Err(map_db_err(e)),
51	            };
52	        };
53	
54	        let stored = StoredRoleRow {
55	            template_id: &existing.template_id,
56	            scope_kinds: &existing.scope_kinds,
57	            description: existing.description.as_deref(),
58	            system: existing.system,
59	        };
60	        if role_row_matches(&stored, role_def) {
61	            return Ok(RoleOutcome::Unchanged);
62	        }
63	
64	        // `created_at` is preserved: only the code-defined columns converge.
65	        let active = role::ActiveModel {
66	            key: Set(role_def.key.clone()),
67	            template_id: Set(role_def.template_id.clone()),
68	            scope_kinds: Set(scope_kinds_json(&role_def.scope_kinds)),
69	            description: Set(description),
70	            system: Set(role_def.system),
71	            created_at: Set(existing.created_at),
72	        };
73	        active.update(&self.db).await.map_err(map_db_err)?;
74	        Ok(RoleOutcome::Updated)
75	    }
76	
77	    async fn orphaned_system_role_keys(&self, known: &[&str]) -> Result<Vec<String>, AuthzError> {
78	        // `ORDER BY key`, exactly as `orphaned_system_policy_ids` orders by `policy_id`: boot
79	        // logs one WARN line per orphan, so an unordered scan would reshuffle a boot's lines run
80	        // to run (and make any multi-orphan test flaky). Contract, not implementation detail.
81	        // Projected to the key column, matching `orphaned_system_policy_ids`: only the key is used.
82	        let keys: Vec<String> = role::Entity::find()
83	            .select_only()
84	            .column(role::Column::Key)
85	            .filter(role::Column::System.eq(true))
86	            .order_by_asc(role::Column::Key)
87	            .into_tuple()
88	            .all(&self.db)
89	            .await
90	            .map_err(map_db_err)?;
91	        Ok(keys.into_iter().filter(|k| !known.contains(&k.as_str())).collect())
92	    }
93	
94	    async fn existing_role_keys(&self) -> Result<Vec<String>, AuthzError> {
95	        // EVERY row, deliberately unfiltered by `system` — this feeds boot's fatal-vs-survivable
96	        // decision, and an operator's own non-system row at a code-defined key still means the
97	        // key exists (the INSERT would collide, not vanish). Narrowing it would report a present
98	        // row as missing and turn a survivable failure fatal.
99	        role::Entity::find().select_only().column(role::Column::Key).into_tuple().all(&self.db).await.map_err(map_db_err)
100	    }
101	}
