67	// `Clone` lets the composition root hold a store handle inside a `#[derive(Clone))]`
68	// service (mirrors `PgOrganizationRepository`'s precedent) — cheap: `DatabaseConnection`
69	// clones an `Arc`-backed pool handle, and `Generations` is `Arc`-backed too.
70	#[derive(Clone)]
71	pub struct PgPolicyStore {
72	    db: DatabaseConnection,
73	    gens: Generations,
74	}
75	
76	impl PgPolicyStore {
77	    #[must_use]
78	    pub fn new(db: DatabaseConnection, gens: Generations) -> Self {
79	        PgPolicyStore { db, gens }
80	    }
81	
82	    /// Best-effort `policy_gen` bump (spec §7/D11): logged and swallowed on error — mirrors
83	    /// `pg_organizations.rs::bump_entity_gen`/`bump_policy_gen` exactly: `put`/`delete`'s
84	    /// mutation already committed, so a Redis-down bump failure must never fail an
85	    /// already-successful write; it just means the change lands on the policy snapshot's TTL
86	    /// backstop — `policy_cache_ttl_secs + refresh_interval_secs`, NOT the decision cache's own
87	    /// TTL — instead of immediately (D11: a swallowed bump degrades to backstop-bounded
88	    /// staleness). The decision cache needs no expiry of its own to follow: its key's policy
89	    /// component is the compiled set's `content_hash` (SMA-470 D4), so that reload rotates the
90	    /// key space for it — which is also why the claim has to be phrased this way, since
91	    /// `MemoryDecisionCache` has no TTL at all. Distinct from the public
92	    /// `PolicyStore::bump_policy_gen` trait method (which forces a bump and propagates a
93	    /// failure to the caller by design).
94	    async fn bump_policy_gen_best_effort(&self) {
95	        if let Err(err) = self.gens.bump_policy_gen().await {
96	            tracing::warn!(error = %err, "pg_policies: policy_gen bump failed after a committed write — authz decisions may be stale until the policy snapshot's TTL backstop reloads");
97	        }
98	    }
99	}
