101	/// Compares a stored `policy` row's content-bearing fields against an incoming
102	/// `PolicyDocument` — used by `put`'s unique-constraint-violation branch to distinguish an
103	/// idempotent same-content race from a genuine different-content conflict. Timestamps are
104	/// deliberately excluded: the two racers' `created_at`/`updated_at` differ by construction
105	/// even when the policy content itself is identical.
106	fn policy_content_matches(stored: &policy::Model, doc: &PolicyDocument) -> bool {
107	    stored.kind == kind_to_str(doc.kind)
108	        && stored.source == doc.source
109	        && stored.description == if doc.description.is_empty() { None } else { Some(doc.description.clone()) }
110	        && stored.system == doc.system
111	}
112	
113	/// Borrows a stored row as the classifier's input view.
114	///
115	/// Two deliberate coercions, both of which this module elsewhere refuses to make — read the
116	/// reasoning before "fixing" either:
117	///
118	/// - `starter_revision` is `i32` in Postgres (there is no unsigned integer type). A negative
119	///   value can only come from a hand edit; clamping it to `0` makes it read as "oldest
120	///   possible", which CONVERGES the row rather than deferring to it. Deferring on a
121	///   hand-written negative would be the exploitable direction.
122	/// - An unparseable `kind` degrades to `Static` here, where `model_to_doc` rightly surfaces
123	///   it as `Backend`. The difference is what the value feeds: `model_to_doc` feeds the
124	///   decision path, where a wrong kind silently changes authorization, so it must fail loudly.
125	///   This value feeds only the CLASSIFIER, and a corrupt `kind` can only come from a hand edit
126	///   — whose fingerprint therefore cannot match, so the row classifies `ExternallyModified` and
127	///   gets converged (repairing the bad `kind`) no matter which variant is guessed here.
128	///   Returning an error instead would make a corrupt row permanently unrepairable, which is the
129	///   opposite of this function's purpose.
130	fn stored_row(model: &policy::Model) -> StoredPolicyRow<'_> {
131	    StoredPolicyRow {
132	        kind: kind_from_str(&model.kind).unwrap_or(PolicyKind::Static),
133	        source: &model.source,
134	        description: model.description.as_deref().unwrap_or(""),
135	        system: model.system,
136	        fingerprint: model.content_fingerprint.as_deref(),
137	        revision: model.starter_revision.map(|r| u32::try_from(r).unwrap_or(0)),
138	    }
139	}
140	
141	/// The full column set a converge writes. `created_at` is deliberately preserved from the
142	/// stored row — the incoming `doc.created_at` is `starter_policies()`'s own `Utc::now()` and
143	/// must never rewrite history. `system` is always set back to `true`: clearing it is one of the
144	/// things a converge exists to undo.
145	fn converged_model(doc: &PolicyDocument, created_at: DateTime<Utc>, now: DateTime<Utc>, revision: u32) -> policy::ActiveModel {
146	    policy::ActiveModel {
147	        policy_id: Set(doc.policy_id.clone()),
148	        kind: Set(kind_to_str(doc.kind).to_string()),
149	        source: Set(doc.source.clone()),
150	        description: Set(if doc.description.is_empty() { None } else { Some(doc.description.clone()) }),
151	        system: Set(true),
152	        created_at: Set(created_at),
153	        updated_at: Set(now),
154	        content_fingerprint: Set(Some(content_fingerprint(doc.kind, &doc.source, &doc.description))),
155	        starter_revision: Set(Some(i32::try_from(revision).unwrap_or(i32::MAX))),
156	    }
157	}
