159	/// Shared with `pg_system_roles.rs` (SMA-477): both adapters map the same SeaORM `DbErr`
160	/// into the same `AuthzError::Backend`.
161	pub(crate) fn map_db_err(e: DbErr) -> AuthzError {
162	    AuthzError::Backend(Box::new(e))
163	}
164	
165	/// Maps a [`recover_txn`] failure (an opaque `&dyn Transaction` that isn't a
166	/// `SeaOrmTransaction` — never happens in production, only a misbuilt fake could trigger it)
167	/// into `AuthzError::Backend`, mirroring `pg_role_grants.rs`'s `map_txn_err`.
168	fn map_txn_err(e: RepositoryError) -> AuthzError {
169	    AuthzError::Backend(Box::new(e))
170	}
171	
172	/// A stored-error helper for the unique-violation-but-no-row-on-re-read shouldn't-happen
173	/// case — a data-integrity break, surfaced as `Backend`, never a silent default (mirrors
174	/// `pg_role_grants.rs::backend_err`).
175	fn backend_err(msg: impl std::fmt::Display) -> AuthzError {
176	    AuthzError::Backend(Box::new(std::io::Error::other(msg.to_string())))
177	}
