179	/// Delegates to the core encoding (SMA-477): the audit entry that records an overwritten row's
180	/// `kind` renders it with the same function, so the two cannot drift.
181	fn kind_to_str(kind: PolicyKind) -> &'static str {
182	    policy_kind_str(kind)
183	}
184	
185	/// A stored `kind` value outside `{static, template}` is a data-integrity break (the
186	/// `ck_policy_kind` CHECK should prevent it) — surfaced as `Backend`, never a silent
187	/// default, mirroring `pg_memberships.rs::parse_status`.
188	fn kind_from_str(raw: &str) -> Result<PolicyKind, AuthzError> {
189	    match raw {
190	        "static" => Ok(PolicyKind::Static),
191	        "template" => Ok(PolicyKind::Template),
192	        other => Err(AuthzError::Backend(Box::new(std::io::Error::other(format!("bad policy kind: {other}"))))),
193	    }
194	}
