196	/// Builds the insertable/updatable `policy` row from a domain `PolicyDocument`. An empty
197	/// `description` is stored as `NULL` (the column is nullable; the domain field is not) so
198	/// an untouched-by-hand row round-trips byte-for-byte either way.
199	///
200	/// `created_at` is threaded in separately from `doc`: on INSERT it's `doc.created_at` (the
201	/// row is new), but on UPDATE the caller must pass the *stored* row's `created_at` — the
202	/// incoming `doc.created_at` is untrusted client input and must never overwrite the
203	/// original creation timestamp.
204	fn doc_to_model(doc: &PolicyDocument, created_at: DateTime<Utc>) -> policy::ActiveModel {
205	    policy::ActiveModel {
206	        policy_id: Set(doc.policy_id.clone()),
207	        kind: Set(kind_to_str(doc.kind).to_string()),
208	        source: Set(doc.source.clone()),
209	        description: Set(if doc.description.is_empty() { None } else { Some(doc.description.clone()) }),
210	        system: Set(doc.system),
211	        created_at: Set(created_at),
212	        updated_at: Set(doc.updated_at),
213	        // SMA-477: NEVER `Set` here. `doc_to_model` is shared with `put_in`, which serves the
214	        // public `PutPolicy` API — an operator-authored policy must carry no fingerprint and no
215	        // starter revision. `NotSet` omits the column from the INSERT (DB default NULL) and from
216	        // the UPDATE SET clause (existing value untouched); only `reconcile_system` writes them.
217	        content_fingerprint: NotSet,
218	        starter_revision: NotSet,
219	    }
220	}
221	
222	fn model_to_doc(model: policy::Model) -> Result<PolicyDocument, AuthzError> {
223	    Ok(PolicyDocument {
224	        policy_id: model.policy_id,
225	        kind: kind_from_str(&model.kind)?,
226	        source: model.source,
227	        description: model.description.unwrap_or_default(),
228	        system: model.system,
229	        created_at: model.created_at,
230	        updated_at: model.updated_at,
231	    })
232	}
