234	#[async_trait]
235	impl PolicyStore for PgPolicyStore {
236	    async fn list_all(&self) -> Result<Vec<PolicyDocument>, AuthzError> {
237	        // REPEATABLE READ: every row this transaction sees is a single consistent snapshot,
238	        // even if a concurrent `put`/`delete` commits mid-read (port doc contract).
239	        let txn = self.db.begin_with_config(Some(IsolationLevel::RepeatableRead), None).await.map_err(map_db_err)?;
240	        let models = policy::Entity::find().all(&txn).await.map_err(map_db_err)?;
241	        txn.commit().await.map_err(map_db_err)?;
242	
243	        models.into_iter().map(model_to_doc).collect()
244	    }
245	
246	    async fn put(&self, doc: &PolicyDocument) -> Result<(), AuthzError> {
247	        // Thin one-shot-`UnitOfWork` wrapper (SMA-446 Slice B Task B5), mirroring
248	        // `PgRoleGrantStore::grant`: open a `SeaOrmTransaction`, drive the write via
249	        // `put_in`, commit, then best-effort bump — skipped entirely when the outcome is an
250	        // idempotent absorb (module docs: the winning writer already bumped for this row).
251	        let txn = self.db.begin().await.map_err(map_db_err)?;
252	        let tx: Box<dyn Transaction> = Box::new(SeaOrmTransaction { txn });
253	        let outcome = self.put_in(&*tx, doc).await?;
254	        tx.commit().await.map_err(map_txn_err)?;
255	        if !matches!(outcome, PutOutcome::AbsorbedIdempotent) {
256	            self.bump_policy_gen_best_effort().await;
257	        }
258	        Ok(())
259	    }
260	
261	    async fn delete(&self, policy_id: &str) -> Result<(), AuthzError> {
262	        // Thin one-shot-`UnitOfWork` wrapper, mirroring `put` above / `PgRoleGrantStore::
263	        // revoke`.
264	        let txn = self.db.begin().await.map_err(map_db_err)?;
265	        let tx: Box<dyn Transaction> = Box::new(SeaOrmTransaction { txn });
266	        let existed = self.delete_in(&*tx, policy_id).await?;
267	        tx.commit().await.map_err(map_txn_err)?;
268	        if existed {
269	            self.bump_policy_gen_best_effort().await;
270	        }
271	        Ok(())
272	    }
273	
274	    async fn put_in(&self, tx: &dyn Transaction, doc: &PolicyDocument) -> Result<PutOutcome, AuthzError> {
275	        validate_policy(&doc.source)?;
276	
277	        // SMA-477 D6: the starter policy ids are code-owned, reserved whether or not they are
278	        // seeded yet. Rejecting on the ID (not on a stored row's `system` flag) is what closes
279	        // the `UPDATE policy SET system = false` bypass — an operator can never create a
280	        // non-system row at one of these ids for a later release to trip over. Reuses
281	        // `SystemImmutable` so the existing `TenancyError` and API mappings are unchanged.
282	        if authz_roles::is_starter_policy_id(&doc.policy_id) {
283	            return Err(AuthzError::SystemImmutable(doc.policy_id.clone()));
284	        }
285	
286	        let txn = recover_txn(tx).map_err(map_txn_err)?;
287	
288	        let existing = policy::Entity::find_by_id(doc.policy_id.clone()).lock_exclusive().one(txn).await.map_err(map_db_err)?;
289	        if let Some(existing) = &existing
290	            && existing.system
291	        {
292	            return Err(AuthzError::SystemImmutable(doc.policy_id.clone()));
293	        }
294	
295	        // On UPDATE, preserve the stored row's `created_at` — only INSERT takes it from
296	        // `doc` (the row is genuinely new then). This must read the fetched `existing`, not
