406	        let existing = policy::Entity::find_by_id(doc.policy_id.clone()).lock_exclusive().one(&txn).await.map_err(map_db_err)?;
407	        let outcome = classify_starter_policy(existing.as_ref().map(stored_row), doc, revision);
408	        let now = Utc::now();
409	
410	        let outcome = match (&outcome, existing) {
411	            (StarterPolicyOutcome::Unchanged | StarterPolicyOutcome::StaleBinary { .. }, _) => outcome,
412	            (_, Some(row)) => {
413	                converged_model(doc, row.created_at, now, revision).update(&txn).await.map_err(map_db_err)?;
414	                outcome
415	            }
416	            (_, None) => {
417	                // Our existence check and this INSERT are not atomic: two replicas can both see
418	                // an absent row. Run it on a SAVEPOINT so a unique violation rolls back only the
419	                // insert, not the caller's transaction — the `put_in` pattern, except we re-read
420	                // WITH the row lock, because unlike `put_in` we may go on to UPDATE.
421	                let sp = txn.begin().await.map_err(map_db_err)?;
422	                match converged_model(doc, doc.created_at, now, revision).insert(&sp).await {
423	                    Ok(_) => {
424	                        sp.commit().await.map_err(map_db_err)?;
425	                        StarterPolicyOutcome::Absent
426	                    }
427	                    Err(e) if matches!(e.sql_err(), Some(SqlErr::UniqueConstraintViolation(_))) => {
428	                        sp.rollback().await.map_err(map_db_err)?;
429	                        let winner = policy::Entity::find_by_id(doc.policy_id.clone())
430	                            .lock_exclusive()
