432	                            .await
433	                            .map_err(map_db_err)?
434	                            .ok_or_else(|| backend_err(format!("policy {}: unique-constraint violation on insert but no row found on re-read", doc.policy_id)))?;
435	                        // Re-classify against whoever won. This cannot recurse into the insert
436	                        // branch — the row provably exists now — so it terminates.
437	                        let re = classify_starter_policy(Some(stored_row(&winner)), doc, revision);
438	                        if !matches!(re, StarterPolicyOutcome::Unchanged | StarterPolicyOutcome::StaleBinary { .. }) {
439	                            converged_model(doc, winner.created_at, now, revision).update(&txn).await.map_err(map_db_err)?;
440	                        }
441	                        re
442	                    }
443	                    Err(e) => return Err(map_db_err(e)),
444	                }
445	            }
446	        };
447	
448	        txn.commit().await.map_err(map_db_err)?;
449	        if outcome.content_changed() {
450	            self.bump_policy_gen_best_effort().await;
451	        }
452	        Ok(outcome)
