459	        // Projected to the id column rather than `find().all()`: only the id is ever used, and a
460	        // starter policy's `source` runs to multiple KB, so loading whole rows here would pull the
461	        // entire system-owned policy set's Cedar text across the wire to throw it away.
462	        let ids: Vec<String> = policy::Entity::find()
463	            .select_only()
464	            .column(policy::Column::PolicyId)
465	            .filter(policy::Column::System.eq(true))
466	            .order_by_asc(policy::Column::PolicyId)
467	            .into_tuple()
468	            .all(&self.db)
469	            .await
470	            .map_err(map_db_err)?;
471	        Ok(ids.into_iter().filter(|id| !known.contains(&id.as_str())).collect())
472	    }
